    47→import { toast } from "sonner";
    48→import { useCurrentOrg } from "../../../use-current-org";
    49→import { OrganizationInviteMemberForm } from "./org-invite-member-form";
    50→
    51→type OrgMembersFormProps = {
    52→  members: OrgMembers;
    53→  maxMembers: number;
    54→  invitations: Invitation[];
    55→};
    56→
    57→export const OrgMembersForm = ({
    58→  maxMembers,
    59→
    60→  members,
    61→  invitations,
    62→}: OrgMembersFormProps) => {
    63→  const router = useRouter();
    64→  const session = useSession();
    65→  const org = useCurrentOrg();
    66→  const [optimisticMembers, updateOptimisticMembers] = useOptimistic(
    67→    members,
    68→    (state, update: { type: string; memberId: string; role?: string }) => {
    69→      if (update.type === "DELETE") {
    70→        return state.filter((member) => member.id !== update.memberId);
    71→      } else if (update.type === "UPDATE_ROLE" && update.role) {
    72→        return state.map((member) =>
    73→          member.id === update.memberId
    74→            ? { ...member, role: update.role ?? "member" }
    75→            : member,
    76→        );
    77→      }
    78→      return state;
    79→    },
    80→  );
    81→
    82→  const updateRoleMutation = useMutation({
    83→    mutationFn: async ({
    84→      memberId,
    85→      role,
    86→    }: {
    87→      memberId: string;
    88→      role: AuthRole;
    89→    }) => {
    90→      // Using BetterAuth client to update member role
    91→      return unwrapSafePromise(
    92→        authClient.organization.updateMemberRole({
    93→          memberId,
    94→          role,
    95→        }),
    96→      );
    97→    },
    98→    onMutate: ({ memberId, role }) => {
    99→      // Optimistically update the UI
   100→      updateOptimisticMembers({ type: "UPDATE_ROLE", memberId, role });
   101→    },
   102→    onSuccess: () => {
   103→      toast.success("Member role updated successfully");
   104→      router.refresh();
   105→    },
   106→    onError: (error) => {
   107→      toast.error(error.message);
   108→      router.refresh(); // Refresh to get the actual state
   109→    },
   110→  });
   111→
   112→  const removeMemberMutation = useMutation({
   113→    mutationFn: async (memberId: string) => {
   114→      if (!org?.id) {
   115→        throw new Error("Organization ID is required");
   116→      }
   117→      // Using BetterAuth client to remove member
   118→      await authClient.organization.removeMember({
   119→        memberIdOrEmail: memberId,
   120→        organizationId: org.id,
   121→      });
   122→      return memberId;
   123→    },
   124→    onMutate: (memberId) => {
   125→      // Optimistically update the UI
   126→      updateOptimisticMembers({ type: "DELETE", memberId });
   127→    },
   128→    onSuccess: () => {
   129→      toast.success("Member removed successfully");
   130→      router.refresh();
   131→    },
   132→    onError: () => {
   133→      toast.error("Failed to remove member");
   134→      router.refresh(); // Refresh to get the actual state
   135→    },
   136→  });
   137→
   138→  const removeInvitationMutation = useMutation({
   139→    mutationFn: async (invitationId: string) => {
   140→      await authClient.organization.cancelInvitation({
   141→        invitationId,
   142→      });
   143→    },
   144→    onSuccess: () => {
   145→      toast.success("Invitation removed successfully");
   146→      router.refresh();
   147→    },
   148→    onError: () => {
   149→      toast.error("Failed to remove invitation");
   150→      router.refresh(); // Refresh to get the actual state
   151→    },
   152→  });
   153→
   154→  const handleRemoveMember = (memberId: string) => {
   155→    dialogManager.confirm({
   156→      title: "Remove member",
   157→      description:
   158→        "Are you sure you want to remove this member from the organization?",
   159→      action: {
   160→        label: "Remove",
   161→        onClick: async () => {
   162→          removeMemberMutation.mutate(memberId);
   163→        },
   164→      },
   165→    });
   166→  };
   167→
   168→  return (
   169→    <Card>
   170→      <CardHeader className="flex w-full flex-row items-center gap-4 space-y-0">
   171→        <div className="flex flex-col gap-2">
   172→          <CardTitle>Members</CardTitle>
   173→          <CardDescription>
   174→            Teammates that have access to this workspace.
   175→          </CardDescription>
   176→        </div>
   177→        <div className="flex-1"></div>
   178→        <div>
   179→          {optimisticMembers.length < maxMembers ? (
   180→            <OrganizationInviteMemberForm />
   181→          ) : (
   182→            <Button
   183→              type="button"
   184→              variant="outline"
   185→              onClick={(e) => {
   186→                e.preventDefault();
   187→                e.stopPropagation();
   188→
   189→                const dialogId = dialogManager.confirm({
   190→                  title: "Oh no! You've reached the maximum number of members",
   191→                  description: (
   192→                    <>
   193→                      <Typography>
   194→                        You can't add more members to your organization. Please
   195→                        upgrade your plan to add more members.
   196→                      </Typography>
   197→                      <Alert className="flex flex-col gap-2">
   198→                        <Progress
   199→                          value={(optimisticMembers.length / maxMembers) * 100}
   200→                        />
   201→                        <Typography variant="small">
   202→                          You have {optimisticMembers.length} members out of{" "}
   203→                          {maxMembers} members
   204→                        </Typography>
   205→                      </Alert>
   206→                    </>
   207→                  ),
   208→                  action: {
   209→                    label: "Upgrade your plan",
   210→                    onClick: () => {
   211→                      openGlobalDialog("org-plan");
   212→                      dialogManager.close(dialogId);
   213→                    },
   214→                  },
   215→                });
   216→              }}
   217→            >
   218→              <Zap className="mr-2" size={16} />
   219→              Invite
   220→            </Button>
   221→          )}
   222→        </div>
   223→      </CardHeader>
   224→      <Tabs defaultValue="members" className="mt-4 gap-0">
   225→        <TabsList className="flex gap-4 px-6">
   226→          <TabsTrigger
   227→            value="members"
   228→            className="text-muted-foreground hover:bg-accent/50 data-[state=active]:border-foreground translate-y-px rounded-t-md border-b px-3 py-2 text-sm transition"
   229→          >
   230→            Members
