   235→          >
   236→            Invitations
   237→          </TabsTrigger>
   238→        </TabsList>
   239→        <TabsContent value="members" className="mt-0 border-t pt-4">
   240→          <CardContent className="flex flex-col">
   241→            {optimisticMembers.map((member) => {
   242→              const isCurrentUser = member.user.id === session.data?.user.id;
   243→              return (
   244→                <div key={member.id}>
   245→                  <div className="my-2 flex flex-wrap items-center gap-2">
