     3→import type { Metadata } from "next";
     4→import { Suspense } from "react";
     5→import { InjectCurrentOrgStore } from "./use-current-org";
     6→
     7→export async function generateMetadata(
     8→  props: LayoutProps<"/orgs/[orgSlug]">,
     9→): Promise<Metadata> {
    10→  const params = await props.params;
    11→  return orgMetadata(params.orgSlug);
    12→}
    13→
    14→export default async function RouteLayout(
    15→  props: LayoutProps<"/orgs/[orgSlug]">,
    16→) {
    17→  return (
    18→    <>
    19→      {props.children}
    20→      <Suspense fallback={null}>
    21→        <LayoutPage />
    22→      </Suspense>
    23→    </>
    24→  );
    25→}
    26→
    27→const LayoutPage = async () => {
