### 8. GESTION DES ABONNEMENTS

#### Récupération de l'Abonnement Actif
**Fichier**: `/Users/yoannandrieux/Projets/moodday/src/lib/organizations/get-org-subscription.ts`

```typescript
export const getOrgActiveSubscription = async (
  organizationId: string,
): Promise<...> => {
  const cacheKey = CacheKeys.orgSubscription(organizationId);

  // 1. Essayer le cache Redis
  try {
    const cached = await redisClient.get(cacheKey);
    if (cached) return JSON.parse(cached);
  } catch (error) {
    logger.error("[Cache Error]", error);
  }

  // 2. Récupérer de la base de données
  const subscription = await prisma.subscription.findFirst({
    where: {
      referenceId: organizationId,
      OR: [
        { status: "active" },
        { status: "trialing" },
        { status: "past_due" },
      ],
    },
  });

  if (!subscription?.stripeSubscriptionId) return null;

  try {
    // 3. Vérifier le statut avec Stripe
    const stripeSubscription = await stripe.subscriptions.retrieve(
      subscription.stripeSubscriptionId,
    );

    // 4. Mettre à jour la BD si le statut a changé
    if (!["active", "trialing", "past_due"].includes(stripeSubscription.status)) {
      await prisma.subscription.update({
        where: { id: subscription.id },
        data: {
          status: stripeSubscription.status,
          ...(stripeSubscription.status === "canceled" && { plan: "free" }),
        },
      });
      return null;
    }

    const result = {
      ...subscription,
      status: stripeSubscription.status,
      cancelAtPeriodEnd: stripeSubscription.cancel_at_period_end,
      limits: getPlanLimits(
        subscription.plan,
        subscription.overrideLimits as OverrideLimits | null,
      ),
    };

    // 5. Mettre en cache pour 1 heure
    await redisClient.setex(cacheKey, 3600, JSON.stringify(result));
    return result;
  } catch (error) {
    // Fallback: retourner la subscription en cache court (5 min)
    const result = {
      ...subscription,
      limits: getPlanLimits(subscription.plan, null),
    };
    await redisClient.setex(cacheKey, 300, JSON.stringify(result));
    return result;
  }
};
```

